//! OpenAPI generation uses the runtime router and serde DTOs; no infrastructure is started.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use std::collections::BTreeMap;
use tackt_primitives::{CoreUser, CreateCoreUser, Source, UserStatus};
use utoipa::ToSchema;
use uuid::Uuid;

// The second name is the Path type generated by #[utoipa::path]. Both runtime routing
// and documentation use its annotated paths and methods, without a second registry.
macro_rules! routes {
    ($($handler:path => $path:path),+ $(,)?) => {{
        #[derive(utoipa::OpenApi)]
        #[openapi(paths($($handler),+))]
        struct Api;
        let router = axum::Router::new();
        $(let router = router.route(&<$path as utoipa::Path>::path(),
            $crate::openapi::method_router::<$path, _, _, _>($handler));)+
        (router, <Api as utoipa::OpenApi>::openapi())
    }};
}
pub(crate) use routes;

pub(crate) fn method_router<
    P: utoipa::Path,
    H: axum::handler::Handler<T, S>,
    T: 'static,
    S: Clone + Send + Sync + 'static,
>(
    handler: H,
) -> axum::routing::MethodRouter<S> {
    use axum::routing::{MethodFilter, MethodRouter};
    use utoipa::openapi::path::HttpMethod;
    P::methods()
        .into_iter()
        .fold(MethodRouter::new(), |router, method| {
            let filter = match method {
                HttpMethod::Get => MethodFilter::GET,
                HttpMethod::Post => MethodFilter::POST,
                HttpMethod::Put => MethodFilter::PUT,
                HttpMethod::Delete => MethodFilter::DELETE,
                HttpMethod::Patch => MethodFilter::PATCH,
                HttpMethod::Options => MethodFilter::OPTIONS,
                HttpMethod::Head => MethodFilter::HEAD,
                HttpMethod::Trace => MethodFilter::TRACE,
            };
            router.on(filter, handler.clone())
        })
}

// Serde remote derives check these documentation adapters against the actual domain types,
// without adding a transport/documentation dependency to tackt-primitives.
#[allow(dead_code)]
#[derive(Serialize, Deserialize, ToSchema)]
#[serde(remote = "CoreUser")]
#[schema(as = CoreUser)]
pub(crate) struct CoreUserSchema {
    id: Uuid,
    external_id: String,
    #[schema(value_type = UserStatusSchema)]
    status: UserStatus,
    #[serde(default)]
    #[schema(required = true)]
    beta_access: bool,
    #[schema(value_type = BTreeMap<String, String>)]
    accounts: BTreeMap<Source, String>,
    metadata: Value,
    created_at: DateTime<Utc>,
    updated_at: DateTime<Utc>,
}

#[allow(dead_code)]
#[derive(Serialize, Deserialize, ToSchema)]
#[serde(remote = "CreateCoreUser")]
#[schema(as = CreateCoreUser)]
pub(crate) struct CreateCoreUserSchema {
    #[schema(min_length = 1, max_length = 255)]
    external_id: String,
    #[serde(default = "tackt_primitives::empty_json_object")]
    #[schema(value_type = Object)]
    metadata: Value,
}

#[allow(dead_code)]
#[derive(Serialize, Deserialize, ToSchema)]
#[serde(remote = "UserStatus", rename_all = "snake_case")]
#[schema(as = UserStatus)]
pub(crate) enum UserStatusSchema {
    Pending,
    Active,
    Restricted,
    Closed,
}

#[allow(dead_code)]
#[derive(Serialize, Deserialize, ToSchema)]
#[serde(remote = "Source", rename_all = "snake_case")]
#[schema(as = Source)]
pub(crate) enum SourceSchema {
    Ethereum,
    Hyperliquid,
}

/// Builds the complete mounted HTTP contract without credentials or database/broker access.
pub fn document() -> Value {
    let (_, api) = crate::api::documented_routes(crate::auth::OperatorAuth::new(String::new()));
    let mut spec = serde_json::to_value(api).expect("OpenAPI serialization");
    // Include path-only schemas explicitly. Wallet response shapes overlap.
    spec["components"]["schemas"]["Source"] =
        serde_json::to_value(<SourceSchema as utoipa::PartialSchema>::schema()).unwrap();
    let challenge = spec["components"]["schemas"]["LoginChallenge"]
        .as_object_mut()
        .unwrap();
    let variants = challenge.remove("oneOf").unwrap();
    challenge.insert("anyOf".into(), variants);
    for variant in spec["components"]["schemas"]["Proof"]["oneOf"]
        .as_array_mut()
        .unwrap()
    {
        variant["additionalProperties"] = json!(false);
    }
    spec["info"] = json!({
        "title": "Tackt Core API", "version": env!("CARGO_PKG_VERSION"),
        "description": "Core-issued access JWTs last up to 15 minutes. Refresh sessions last 30 days. Logout blocks refresh immediately; issued access JWTs remain valid until expiry. User routes use camelCase and Unix-millisecond timestamps; legacy operator routes retain snake_case and RFC3339 timestamps."
    });
    spec["components"]["securitySchemes"] = json!({
        "AccessCookie": {"type":"apiKey", "in":"cookie", "name":"__Secure-tackt-access", "description":"Core-issued access JWT. HttpOnly; Secure; SameSite=Strict; Path=/api. Do not combine with bearer authentication."},
        "RefreshCookie": {"type":"apiKey", "in":"cookie", "name":"__Secure-tackt-refresh", "description":"Rotating opaque refresh credential; an access JWT is not required."},
        "UserBearer": {"type":"http", "scheme":"bearer", "bearerFormat":"JWT", "description":"Core-issued JWT; requires matching X-User-Id."},
        "UserId": {"type":"apiKey", "in":"header", "name":"X-User-Id", "description":"UUID matching the verified JWT subject; required only with UserBearer."},
        "OperatorBearer": {"type":"http", "scheme":"bearer", "description":"Shared CORE_API_OPERATOR_TOKEN, separate from user JWTs."}
    });
    spec["components"]["schemas"]["ErrorResponse"] = json!({
        "type":"object", "required":["error"], "properties":{"error":{
            "type":"object", "required":["code","message","sanitized"], "properties":{
                "code":{"type":"string", "description":"Stable SCREAMING_SNAKE_CASE error code"},
                "message":{"type":"string"}, "sanitized":{"type":"boolean", "const":true},
                "details":{"type":"array", "items":{"type":"object", "required":["field","message"], "properties":{"field":{"type":"string"},"message":{"type":"string"}}}}
            }
        }}
    });
    let paths = spec["paths"].as_object_mut().expect("OpenAPI paths");
    for (path, item) in paths {
        for (method, operation) in item.as_object_mut().expect("path item") {
            if ![
                "get", "post", "put", "delete", "patch", "options", "head", "trace",
            ]
            .contains(&method.as_str())
            {
                continue;
            }
            let parameters = operation
                .as_object_mut()
                .unwrap()
                .entry("parameters")
                .or_insert_with(|| json!([]))
                .as_array_mut()
                .unwrap();
            parameters.push(json!({"name":"X-Request-ID", "in":"header", "required":false, "schema":{"type":"string","maxLength":128}, "description":"Echoed when valid, otherwise generated by Core."}));
            if path.starts_with("/api/") && method != "get" {
                parameters.push(json!({"name":"Origin", "in":"header", "required":false, "schema":{"type":"string"}, "description":"Required for requests carrying cookies; must match a configured trusted origin. Any supplied foreign origin is rejected."}));
            }
            if path.starts_with("/v1/users") {
                parameters.push(json!({"name":"X-Operator-Id", "in":"header", "required":false, "schema":{"type":"string","maxLength":128}, "description":"Optional audit attribution; invalid or missing values become operator."}));
            }
            let responses = operation["responses"].as_object_mut().unwrap();
            responses.insert("default".into(), json!({"description":"Sanitized error. Invalid input: 400; invalid credentials: 401; forbidden: 403; missing resource/provider: 404; identity or idempotency conflict: 409; oversized body: 413; media type: 415; internal failure: 500; unavailable dependency or beta redemption: 503.", "content":{"application/json":{"schema":{"$ref":"#/components/schemas/ErrorResponse"}}}}));
            for (status, response) in responses {
                response["headers"] = json!({"X-Request-ID":{"description":"Request correlation ID", "schema":{"type":"string"}}});
                if (path == "/api/v1/auth/sessions" || path == "/api/v1/auth/session-tokens")
                    && status == "201"
                    || path == "/api/v1/users/me/sessions/current" && status == "200"
                {
                    response["headers"]["Set-Cookie"] = json!({"description":"Two separate Set-Cookie headers set or clear __Secure-tackt-access and __Secure-tackt-refresh. HttpOnly; Secure; SameSite=Strict; Path=/api. Credentials never appear in response JSON.", "schema":{"type":"string"}});
                }
            }
        }
    }
    spec
}

/// Stable formatting shared by the export command and snapshot test.
pub fn json() -> String {
    format!(
        "{}\n",
        serde_json::to_string_pretty(&document()).expect("OpenAPI JSON")
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::{Router, body::Body, http::Request};
    use tower::ServiceExt;

    #[utoipa::path(get, path = "/test", responses((status = 200)))]
    async fn read() -> &'static str {
        "read"
    }
    #[utoipa::path(post, path = "/test", responses((status = 200)))]
    async fn write() -> &'static str {
        "write"
    }
    #[utoipa::path(get, path = "/other", responses((status = 200)))]
    async fn other() -> &'static str {
        "other"
    }

    #[tokio::test]
    async fn annotated_routes_dispatch_by_path_and_method() {
        let (router, spec): (Router, _) =
            routes!(read => __path_read, write => __path_write, other => __path_other);
        let spec = serde_json::to_value(spec).unwrap();
        for (method, path, expected) in [
            ("GET", "/test", "read"),
            ("POST", "/test", "write"),
            ("GET", "/other", "other"),
        ] {
            assert!(
                spec["paths"][path]
                    .get(method.to_ascii_lowercase())
                    .is_some()
            );
            let response = router
                .clone()
                .oneshot(
                    Request::builder()
                        .method(method)
                        .uri(path)
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), 200);
            assert_eq!(
                axum::body::to_bytes(response.into_body(), 64)
                    .await
                    .unwrap(),
                expected
            );
        }
        let response = router
            .oneshot(Request::post("/other").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), 405);
    }

    #[test]
    fn signing_and_wallet_lookup_are_not_exposed_in_the_http_contract() {
        let spec = document();
        assert!(
            spec["paths"]
                .as_object()
                .unwrap()
                .keys()
                .all(|path| !path.contains("signed-transactions") && !path.contains("wallets"))
        );
        assert!(
            spec["components"]["schemas"]
                .get("SignTransaction")
                .is_none()
        );
    }

    #[test]
    fn all_schema_references_resolve() {
        fn check(value: &Value, spec: &Value) {
            match value {
                Value::Object(object) => {
                    if let Some(reference) = object.get("$ref").and_then(Value::as_str) {
                        assert!(
                            spec.pointer(reference.strip_prefix('#').unwrap()).is_some(),
                            "unresolved {reference}"
                        );
                    }
                    for value in object.values() {
                        check(value, spec);
                    }
                }
                Value::Array(values) => {
                    for value in values {
                        check(value, spec);
                    }
                }
                _ => {}
            }
        }
        let spec = document();
        check(&spec, &spec);
    }
}
